-- Complete material costing authority: posted BOM + posted worker/direct + period overhead, once each.
create or replace function public.rr_material_lot_cost_v667(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare l record;b numeric:=0;d numeric:=0;o jsonb;ot numeric:=0;begin select * into l from public.rr_upm_lot_registry where canonical_lot_id=p_canonical_lot_id;if not found then raise exception 'Lot not found';end if;select coalesce(sum(total_consumption_cost) filter(where source_module='CATEGORY_BOM'),0),coalesce(sum(total_consumption_cost) filter(where source_module in('DIRECT_ACTUAL','WORKER_ACTUAL')),0) into b,d from public.rr_material_consumption_v805 where lot_no=l.lot_no and upper(data_mode)=upper(p_data_mode);o:=public.rr_costing_overhead_allocation_v406(p_canonical_lot_id,p_data_mode);ot:=coalesce((o->>'total_lot')::numeric,0);return jsonb_build_object('ok',true,'version','V667_COMPLETE_MATERIAL_PATH','lot_no',l.lot_no,'bom_material_lot',round(b,2),'worker_direct_material_lot',round(d,2),'overhead_lot',round(ot,2),'total_material_and_overhead_lot',round(b+d+ot,2),'overhead',o,'rule','POSTED BOM + POSTED WORKER/DIRECT + PERIOD OVERHEAD; NO ESTIMATE/ACTUAL DOUBLE COUNT');end $function$;